96	// Subcomponent: modal "Adicionar freela"
97	// ---------------------------------------------------------------------------
98	
99	type AddMethod = 'link' | 'phone';
100	
101	interface AddWorkerModalProps {
102	  companyId: string;
103	  onClose: () => void;
104	  onAdded: () => void;
105	  addWorker: (workerId: string, source: 'qr' | 'link' | 'phone') => Promise<boolean>;
106	}
107	
108	function AddWorkerModal({ companyId, onClose, onAdded, addWorker }: AddWorkerModalProps) {
109	  const [method, setMethod] = useState<AddMethod>('link');
110	  const [phone, setPhone] = useState('');
111	  const [workerId, setWorkerId] = useState('');
112	  const [loading, setLoading] = useState(false);
113	  const [copied, setCopied] = useState(false);
114	
115	  const { url: inviteUrl } = TeamConnectionService.generateInviteToken(companyId);
116	
117	  const handleCopyLink = async () => {
118	    try {
119	      await navigator.clipboard.writeText(inviteUrl);
120	      setCopied(true);
121	      setTimeout(() => setCopied(false), 2500);
122	    } catch {
123	      // fallback: selecionar o texto
124	    }
125	  };
126	
127	  const handlePhoneSubmit = async () => {
128	    if (!workerId.trim()) return;
129	    setLoading(true);
130	    const ok = await addWorker(workerId.trim(), 'phone');
131	    setLoading(false);
132	    if (ok) {
133	      onAdded();
134	      onClose();
135	    }
136	  };
137	
138	  return (
139	    <div
140	      className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200"
141	      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
142	    >
143	      <div className="bg-white rounded-2xl border-2 border-black shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] w-full max-w-md p-6">
144	        {/* Header */}
145	        <div className="flex items-center justify-between mb-6">
146	          <h2 className="text-2xl font-black uppercase tracking-tight">Adicionar Freela</h2>
147	          <button onClick={onClose} aria-label="Fechar" className="p-2 hover:bg-gray-100 rounded-xl transition-colors">
148	            <X size={20} />
149	          </button>
150	        </div>
151	
152	        {/* Tabs */}
153	        <div className="flex gap-2 mb-6 border-b-2 border-gray-200 pb-1">
154	          {([
155	            { id: 'link' as AddMethod, icon: Link2, label: 'Link' },
156	            { id: 'phone' as AddMethod, icon: Phone, label: 'Telefone' },
157	          ] as const).map((tab) => (
158	            <button
159	              key={tab.id}
160	              onClick={() => setMethod(tab.id)}
161	              className={`flex items-center gap-2 px-4 py-2 rounded-t-xl font-black uppercase text-sm transition-all ${
162	                method === tab.id
163	                  ? 'bg-black text-white translate-y-[2px]'
164	                  : 'text-gray-400 hover:text-black hover:bg-gray-100'
165	              }`}
166	            >
167	              <tab.icon size={16} /> {tab.label}
168	            </button>
169	          ))}
170	          {/* QR: destaque como "em breve" */}
171	          <button
172	            disabled
173	            className="flex items-center gap-2 px-4 py-2 rounded-t-xl font-black uppercase text-sm text-gray-300 cursor-not-allowed"
174	            title="Scanner QR disponível na v1.1"
175	          >
176	            <QrCode size={16} /> QR (v1.1)
177	          </button>
178	        </div>
179	
180	        {/* Conteúdo por método */}
181	        {method === 'link' && (
182	          <div className="space-y-4">
183	            <p className="text-sm font-bold text-gray-600">
184	              Compartilhe este link com o freela. Ele abrirá o Worki e aceitará o convite de entrada na sua equipe.
185	            </p>
186	            <div className="bg-gray-50 border-2 border-black rounded-xl p-4 flex items-center gap-3 font-mono text-xs break-all text-gray-700">
187	              <span className="flex-1">{inviteUrl}</span>
188	            </div>
189	            <button
190	              onClick={handleCopyLink}
191	              className="w-full bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase flex items-center justify-center gap-2 transition-colors"
192	            >
193	              {copied ? <Check size={18} /> : <Copy size={18} />}
194	              {copied ? 'Copiado!' : 'Copiar Link'}
195	            </button>
196	            <p className="text-xs text-gray-400 text-center">
197	              O freela aparecerá em "Aguardando" até aceitar o convite.
198	            </p>
199	          </div>
200	        )}
201	
202	        {method === 'phone' && (
203	          <div className="space-y-4">
204	            <p className="text-sm font-bold text-gray-600">
205	              Digite o <span className="font-black">ID do worker</span> (Worki ID) para adicionar diretamente.
206	              Busca por telefone disponível na v1.1.
207	            </p>
208	            <div className="space-y-2">
209	              <label htmlFor="phone-input" className="text-xs font-bold uppercase tracking-wide">
210	                Worki ID do freela
211	              </label>
212	              <input
213	                id="phone-input"
214	                type="text"
215	                value={phone}
216	                onChange={(e) => { setPhone(e.target.value); setWorkerId(e.target.value); }}
217	                placeholder="Cole o ID do freela aqui"
218	                className="w-full border-2 border-black rounded-xl px-4 py-3 font-bold focus:ring-2 focus:ring-primary outline-none"
219	              />
220	            </div>
221	            <button
222	              onClick={handlePhoneSubmit}
223	              disabled={loading || !workerId.trim()}
224	              className="w-full bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase flex items-center justify-center gap-2 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
225	            >
226	              {loading ? <Loader2 className="animate-spin" size={18} /> : <UserPlus size={18} />}
227	              {loading ? 'Enviando...' : 'Enviar Convite'}
228	            </button>
229	            <p className="text-xs text-gray-400">
230	              Busca por CPF/telefone disponível na v1.1. Por enquanto, peça o Worki ID ao freela.
231	            </p>
232	          </div>
233	        )}
234	      </div>
235	    </div>
236	  );
237	}
