1	/**
2	 * InviteAccept — página de aceite de convite de equipe via link (Slice 1, R1-b).
3	 *
4	 * Rota: /convite/:token  (worker-facing, sob ProtectedRoute)
5	 * Fluxo:
6	 *   1. Lê :token da URL.
7	 *   2. Chama TeamConnectionService.addToTeamByToken(token) (deriva workerId da sessão).
8	 *   3. Exibe loading / sucesso / erro no design neo-brutalista.
9	 *   4. Em sucesso, navega para /my-jobs (tela de equipes/convites do worker).
10	 *
11	 * TODO (v1.1): implementar redirect pós-login para retornar a esta URL quando o
12	 * worker ainda não está autenticado (ProtectedRoute redireciona para / que redireciona
13	 * para /login; o token é perdido). Sugestão: passar ?redirect=/convite/<token> ao login.
14	 */
15	
16	import { useEffect, useState } from 'react';
17	import { useParams, useNavigate } from 'react-router-dom';
18	import { CheckCircle2, XCircle, Loader2, Building2, ArrowRight } from 'lucide-react';
19	import { TeamConnectionService } from '../services/teamConnectionService';
20	import { logError } from '../lib/logger';
21	import PageMeta from '../components/PageMeta';
22	
23	type PageState = 'loading' | 'success' | 'already_exists' | 'error';
24	
25	interface PageData {
26	  state: PageState;
27	  errorMsg?: string;
28	}
29	
30	export default function InviteAccept() {
31	  const { token } = useParams<{ token: string }>();
32	  const navigate = useNavigate();
33	  const [page, setPage] = useState<PageData>({ state: 'loading' });
34	
35	  useEffect(() => {
36	    let active = true;
37	
38	    async function processInvite() {
39	      if (!token) {
40	        if (active) setPage({ state: 'error', errorMsg: 'Link de convite inválido.' });
41	        return;
42	      }
43	
44	      try {
45	        const result = await TeamConnectionService.addToTeamByToken(token);
46	
47	        if (!active) return;
48	
49	        if (result.error) {
50	          setPage({ state: 'error', errorMsg: result.error });
51	          return;
52	        }
53	
54	        if (result.alreadyExists) {
55	          setPage({ state: 'already_exists' });
56	          return;
57	        }
58	
59	        setPage({ state: 'success' });
60	      } catch (err) {
61	        logError('InviteAccept.processInvite', err);
62	        if (active) {
63	          setPage({ state: 'error', errorMsg: 'Ocorreu um erro inesperado. Tente novamente.' });
64	        }
65	      }
66	    }
67	
68	    void processInvite();
69	    return () => { active = false; };
70	  }, [token]);
71	
72	  return (
73	    <div className="min-h-screen bg-[#F4F4F0] flex items-center justify-center p-4">
74	      <PageMeta
75	        title="Convite de Equipe"
76	        description="Aceite o convite para entrar na equipe de uma empresa no Worki."
77	      />
78	
79	      <div className="w-full max-w-md">
80	        {/* Loading */}
81	        {page.state === 'loading' && (
82	          <div className="bg-white border-2 border-black rounded-2xl shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] p-8 text-center">
83	            <div className="w-16 h-16 bg-primary-light border-2 border-black rounded-2xl flex items-center justify-center mx-auto mb-6">
84	              <Building2 size={32} className="text-primary" />
85	            </div>
86	            <h1 className="text-2xl font-black uppercase tracking-tighter mb-2">
87	              Convite de Equipe
88	            </h1>
89	            <div className="flex items-center justify-center gap-3 text-gray-500 mt-6">
90	              <Loader2 className="animate-spin text-primary" size={24} />
91	              <span className="font-bold">Processando convite...</span>
92	            </div>
93	            <div className="mt-6 space-y-3 animate-pulse">
94	              <div className="h-4 bg-gray-200 rounded-xl w-3/4 mx-auto" />
95	              <div className="h-4 bg-gray-200 rounded-xl w-1/2 mx-auto" />
96	            </div>
97	          </div>
98	        )}
99	
100	        {/* Sucesso */}
101	        {page.state === 'success' && (
102	          <div className="bg-white border-2 border-black rounded-2xl shadow-[8px_8px_0px_0px_rgba(0,166,81,1)] p-8 text-center">
103	            <div className="w-16 h-16 bg-primary border-2 border-black rounded-2xl flex items-center justify-center mx-auto mb-6">
104	              <CheckCircle2 size={32} className="text-white" />
105	            </div>
106	            <h1 className="text-2xl font-black uppercase tracking-tighter mb-2">
107	              Convite Aceito!
108	            </h1>
109	            <p className="text-gray-600 font-bold mb-8">
110	              Você entrou para a equipe da empresa. Agora pode receber convites de turno diretamente.
111	            </p>
112	            <button
113	              onClick={() => navigate('/my-jobs')}
114	              className="w-full bg-primary hover:bg-black text-white px-6 py-3 rounded-xl font-black uppercase transition-colors flex items-center justify-center gap-2"
115	            >
116	              Ver Meus Jobs
117	              <ArrowRight size={18} />
118	            </button>
119	          </div>
120	        )}
121	
122	        {/* Já existe (idempotência) */}
123	        {page.state === 'already_exists' && (
124	          <div className="bg-white border-2 border-black rounded-2xl shadow-[8px_8px_0px_0px_rgba(0,166,81,1)] p-8 text-center">
125	            <div className="w-16 h-16 bg-primary-light border-2 border-black rounded-2xl flex items-center justify-center mx-auto mb-6">
126	              <CheckCircle2 size={32} className="text-primary" />
127	            </div>
128	            <h1 className="text-2xl font-black uppercase tracking-tighter mb-2">
129	              Você já está na equipe
130	            </h1>
131	            <p className="text-gray-600 font-bold mb-8">
132	              Você já tem uma conexão com esta empresa. Não é necessário aceitar novamente.
133	            </p>
134	            <button
135	              onClick={() => navigate('/my-jobs')}
136	              className="w-full bg-primary hover:bg-black text-white px-6 py-3 rounded-xl font-black uppercase transition-colors flex items-center justify-center gap-2"
137	            >
138	              Ver Meus Jobs
139	              <ArrowRight size={18} />
140	            </button>
141	          </div>
142	        )}
143	
144	        {/* Erro */}
145	        {page.state === 'error' && (
146	          <div className="bg-white border-2 border-black rounded-2xl shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] p-8 text-center">
147	            <div className="w-16 h-16 bg-red-50 border-2 border-black rounded-2xl flex items-center justify-center mx-auto mb-6">
148	              <XCircle size={32} className="text-red-500" />
149	            </div>
150	            <h1 className="text-2xl font-black uppercase tracking-tighter mb-2">
151	              Link Inválido
152	            </h1>
153	            <p className="text-gray-600 font-bold mb-2">
154	              {page.errorMsg ?? 'Não foi possível processar este convite.'}
155	            </p>
156	            <p className="text-sm text-gray-400 font-medium mb-8">
157	              Peça à empresa um novo link de convite.
158	            </p>
159	            <button
160	              onClick={() => navigate('/my-jobs')}
161	              className="w-full bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase transition-colors flex items-center justify-center gap-2"
162	            >
163	              Ir para Meus Jobs
164	              <ArrowRight size={18} />
165	            </button>
166	          </div>
167	        )}
168	      </div>
169	    </div>
170	  );
171	}
